            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            width: '28px',
            height: '28px',
            borderRadius: '6px',
            background: '#1f1f1f',
            border: '1px solid #2d2d2d',
            cursor: isDragging ? 'grabbing' : 'grab',
            color: '#777',
            flexShrink: 0,
            transition: 'background 0.15s ease, color 0.15s ease, border 0.15s ease'
