                            const firstModuleId = (template.modules || template.spaces || [])?.[0]?.id || null;
                            setSelectedTemplate(template);
                            setSelectedModuleId(firstModuleId);
                            setShowTemplateSelection(false);
                            setShowSurveyPanel(true);
